<?php
namespace App\Notifications;
use Illuminate\Bus\Queueable; use Illuminate\Notifications\Messages\MailMessage; use Illuminate\Notifications\Notification; use App\Support\MessageTemplates;
class WelcomeNotification extends Notification { use Queueable; public function __construct(public string $name, public string $kind='creator'){} public function via(object $notifiable):array{return ['mail'];} public function toMail(object $notifiable):MailMessage { $team=$this->kind==='agency'; $t=MessageTemplates::get('welcome_'.$this->kind,$team?'Your Quick GIGS agency profile is ready':'Welcome to Quick GIGS, {{name}}',$team?'Your team can add services and work references for admin review.':'Your account is ready. Verify your email, complete your profile and get started.',['name'=>$this->name]); return (new MailMessage)->subject($t['subject'])->greeting('Welcome '.$this->name.'!')->line($t['body'])->line('There are no creator listing, bidding or platform fees.')->action($team?'Open your team profile':($this->kind==='business'?'Open your workspace':'Open your studio'), route($this->kind==='business'?'business.home':'creator.dashboard')); } }
